'use strict';

const practiceStore = 'practice';
const asPracticeStore = 'practice-9702-as';
const preferenceStore = 'preferences';
const preferenceKey = 'interface';
const bankStores = {'0625':practiceStore,'9702-as':asPracticeStore,'0620':'practice-0620','9701-as':'practice-9701-as'};
const defaultPreferences = Object.freeze({bank:'9702-as',removeCorrect:true,revision:0});
const resumeKey = 'last-question';
const resetKey = 'reset-generation';
const studyKey = 'active-study';

function attemptBreakdown(record){
  if(Object.hasOwn(record,'firstCorrect')){
    return {firstCorrect:record.firstCorrect,repeats:record.repeatAttempts,repeatCorrect:record.repeatCorrect};
  }
  const earlier=record.attempts-1;
  const earlierCorrect=record.correct-Number(record.lastCorrect);
  const firstCorrect=!earlier?record.lastCorrect:earlierCorrect===0?false:earlierCorrect===earlier?true:null;
  return {firstCorrect,repeats:firstCorrect===null?0:earlier,
    repeatCorrect:firstCorrect===null?0:record.correct-Number(firstCorrect)};
}

function isInWrongBook(record){
  return record?.inWrongBook??(record?.lastCorrect===false);
}

function nextPracticeRecord(previous,{id,option,isCorrect},removeCorrect=true){
  const split=previous?attemptBreakdown(previous):{firstCorrect:isCorrect,repeats:0,repeatCorrect:0};
  return {id,attempts:(previous?.attempts||0)+1,correct:(previous?.correct||0)+Number(isCorrect),
    lastOption:option,lastCorrect:isCorrect,firstCorrect:split.firstCorrect,
    inWrongBook:!isCorrect||(!removeCorrect&&isInWrongBook(previous)),
    repeatAttempts:split.repeats+Number(Boolean(previous)),
    repeatCorrect:split.repeatCorrect+Number(Boolean(previous)&&isCorrect)};
}

function openProgressDatabase(name){
  return new Promise((resolve,reject)=>{
    let timedOut=false;
    let blockedTimer;
    const request=indexedDB.open(name,6);
    request.onupgradeneeded=event=>{
      // Keep version 1 records. The reset marker is added only when resetting.
      if(!event.oldVersion)request.result.createObjectStore(practiceStore,{keyPath:'id'});
      if(event.oldVersion<4)request.result.createObjectStore(preferenceStore,{keyPath:'id'});
      if(event.oldVersion<5)request.result.createObjectStore(asPracticeStore,{keyPath:'id'});
      if(event.oldVersion<6){
        request.result.createObjectStore(bankStores['0620'],{keyPath:'id'});
        request.result.createObjectStore(bankStores['9701-as'],{keyPath:'id'});
      }
    };
    request.onsuccess=()=>{
      clearTimeout(blockedTimer);
      if(timedOut)request.result.close();
      else resolve(request.result);
    };
    request.onerror=()=>{
      clearTimeout(blockedTimer);
      reject(request.error);
    };
    request.onblocked=()=>{
      // A closing version 1 tab may still be finishing its last write.
      blockedTimer=setTimeout(()=>{
        timedOut=true;
        reject(new Error('学习进度存储正在使用'));
      },2000);
    };
  });
}

class PracticeProgress {
  constructor(onChange,bank='0625'){
    const fileScope=':caiwei-physics:'+location.pathname.replace(/index\.html$/, '');
    this.name='0625-p2-progress'+fileScope;
    this.bank=bank;
    this.store=bankStores[bank]??practiceStore;
    this.records=new Map();
    this.preferences=defaultPreferences;
    this.lastId=null;
    this.study=null;
    this.generation=0;
    this.database=null;
    this.channel=null;
    this.onChange=onChange;
  }

  get persistent(){return Boolean(this.database);}

  async open(){
    try{
      this.database=await openProgressDatabase(this.name);
      const [rows,settings]=await Promise.all([
        this.transact('readonly',store=>store.getAll()),
        this.transact('readonly',store=>store.get(preferenceKey),preferenceStore),
      ]);
      this.applySnapshot(rows,true);
      if(settings)this.preferences=settings.value;
      this.database.onversionchange=()=>this.useMemory();
    }catch{
      this.useMemory();
    }
    if(this.persistent&&typeof BroadcastChannel==='function'){
      try{
        this.channel=new BroadcastChannel(this.name);
        this.channel.onmessage=event=>void this.sync(event.data);
      }catch{
        // The database can still persist progress without cross-tab notifications.
      }
    }
  }

  transact(mode,operation,stores=this.store){
    return new Promise((resolve,reject)=>{
      const transaction=this.database.transaction(stores,mode);
      const primary=Array.isArray(stores)?stores[0]:stores;
      const request=operation(transaction.objectStore(primary),transaction);
      transaction.oncomplete=()=>resolve(request?.result);
      transaction.onabort=()=>reject(transaction.error);
    });
  }

  useMemory(){
    this.database?.close();
    this.database=null;
    this.channel?.close();
    this.channel=null;
    this.onChange();
  }

  applySnapshot(rows,initial=false){
    const generation=rows.find(row=>row.id===resetKey)?.generation||0;
    if(!initial&&generation<=this.generation)return;
    this.generation=generation;
    this.lastId=rows.find(row=>row.id===resumeKey)?.questionId||null;
    this.study=rows.find(row=>row.id===studyKey)?.value||null;
    this.records=new Map(rows.filter(row=>![resumeKey,resetKey,studyKey].includes(row.id)).map(row=>[row.id,row]));
    if(!initial)this.onChange(null,true);
  }

  async sync({generation,record,study,records,preferences,bank=this.bank}){
    if(preferences)this.acceptPreferences(preferences);
    if(bank!==this.bank)return;
    if(generation>this.generation&&this.persistent){
      try{
        this.applySnapshot(await this.transact('readonly',store=>store.getAll()));
      }catch{
        this.useMemory();
      }
    }
    if(record&&generation===this.generation)this.receive(record);
    if(study&&generation===this.generation)this.acceptStudy(study,records||[]);
  }

  async writeCurrent(generation,operation,readPreferences=false){
    let saved=false;
    let latestGeneration;
    await this.transact('readwrite',(store,transaction)=>{
      const request=store.get(resetKey);
      request.onsuccess=()=>{
        latestGeneration=request.result?.generation||0;
        if(latestGeneration!==generation)return;
        if(readPreferences){
          const preference=transaction.objectStore(preferenceStore).get(preferenceKey);
          preference.onsuccess=()=>operation(store,preference.result?.value||defaultPreferences);
        }else{
          operation(store);
        }
        saved=true;
      };
    },readPreferences?[this.store,preferenceStore]:this.store);
    if(!saved)await this.sync({generation:latestGeneration});
    return saved&&generation===this.generation;
  }

  async savePreferences(bank,removeCorrect){
    const values={bank:Object.hasOwn(bankStores,bank)?bank:'0625',removeCorrect:Boolean(removeCorrect)};
    let preferences={...values,revision:this.preferences.revision+1};
    if(this.persistent){
      await this.transact('readwrite',store=>{
        const request=store.get(preferenceKey);
        request.onsuccess=()=>{
          preferences={...values,revision:(request.result?.value?.revision||0)+1};
          store.put({id:preferenceKey,value:preferences});
        };
      },preferenceStore);
    }
    this.acceptPreferences(preferences);
    this.channel?.postMessage({preferences});
  }

  acceptPreferences(preferences){
    if(preferences.revision<=this.preferences.revision)return;
    this.preferences=preferences;
    this.onChange(null,false,false,true);
  }

  async remember(questionId){
    const generation=this.generation;
    this.lastId=questionId;
    if(!this.persistent)return;
    try{
      await this.writeCurrent(generation,store=>store.put({id:resumeKey,questionId}));
    }catch{
      this.useMemory();
    }
  }

  async record(id,option,isCorrect){
    const generation=this.generation;
    const apply=(previous,preferences)=>nextPracticeRecord(previous,{id,option,isCorrect},preferences.removeCorrect);
    let updated;
    if(this.persistent){
      try{
        // The read and increment share one transaction, including across tabs.
        const saved=await this.writeCurrent(generation,(store,preferences)=>{
          const request=store.get(id);
          request.onsuccess=()=>{
            updated=apply(request.result,preferences);
            store.put(updated);
          };
        },true);
        if(!saved)return;
      }catch{
        this.useMemory();
        updated=null;
      }
    }
    if(generation!==this.generation)return;
    updated??=apply(this.records.get(id),this.preferences);
    this.receive(updated);
    this.channel?.postMessage({bank:this.bank,generation,record:updated});
  }

  async changeStudy(change){
    const generation=this.generation;
    let study, authoritative;
    const records=[];
    if(this.persistent){
      const saved=await this.writeCurrent(generation,(store,preferences)=>{
        const request=store.get(studyKey);
        request.onsuccess=()=>{
          authoritative=request.result?.value||null;
          const result=change(authoritative);
          if(!result)return;
          study={...result.study,revision:(authoritative?.revision||0)+1};
          store.put({id:studyKey,value:study});
          for(const attempt of result.attempts||[]){
            const lookup=store.get(attempt.id);
            lookup.onsuccess=()=>{
              const record=nextPracticeRecord(lookup.result,attempt,preferences.removeCorrect);
              store.put(record);records.push(record);
            };
          }
        };
      },true);
      if(!saved)return this.study;
    }else{
      authoritative=this.study;
      const result=change(authoritative);
      if(result){
        study={...result.study,revision:(authoritative?.revision||0)+1};
        for(const attempt of result.attempts||[]){
          records.push(nextPracticeRecord(this.records.get(attempt.id),attempt,this.preferences.removeCorrect));
        }
      }
    }
    if(generation!==this.generation)return this.study;
    if(study){
      this.acceptStudy(study,records);
      this.channel?.postMessage({bank:this.bank,generation,study,records});
    }else if(authoritative){
      this.acceptStudy(authoritative,[]);
    }
    return this.study;
  }

  acceptStudy(study,records){
    let changed=false;
    for(const record of records)changed=this.receive(record,false)||changed;
    if(!this.study||this.study.revision<study.revision){this.study=study;changed=true;}
    if(changed)this.onChange(null,false,true);
  }

  async reset(){
    let generation=this.generation+1;
    if(this.persistent){
      await this.transact('readwrite',store=>{
        const request=store.get(resetKey);
        request.onsuccess=()=>{
          generation=(request.result?.generation||0)+1;
          // Clearing the records and advancing the generation commit together.
          store.clear();
          store.put({id:resetKey,generation});
        };
      });
    }
    if(generation>this.generation)this.applySnapshot([{id:resetKey,generation}]);
    this.channel?.postMessage({bank:this.bank,generation});
  }

  receive(record,notify=true){
    if((this.records.get(record.id)?.attempts||0)>=record.attempts)return false;
    this.records.set(record.id,record);
    if(notify)this.onChange(record.id);
    return true;
  }
}

function renderAccuracyRadar(chart,chapters,selected){
  const svgNamespace='http://www.w3.org/2000/svg';
  const svg=(tag,attributes={})=>{
    const element=document.createElementNS(svgNamespace,tag);
    for(const [key,value] of Object.entries(attributes))element.setAttribute(key,value);
    return element;
  };
  const center=[164,126];
  const point=(index,ratio)=>{
    const angle=-Math.PI/2+index*2*Math.PI/chapters.length;
    const radius=87*ratio;
    return [center[0]+Math.cos(angle)*radius,center[1]+Math.sin(angle)*radius];
  };
  const coordinates=points=>points.map(pair=>pair.join(',')).join(' ');
  const children=[];
  for(const level of [.25,.5,.75,1]){
    children.push(svg('polygon',{points:coordinates(chapters.map((_,i)=>point(i,level))),class:'radar-grid'}));
  }
  for(const i of chapters.keys()){
    const [x,y]=point(i,1);
    children.push(svg('line',{x1:center[0],y1:center[1],x2:x,y2:y,class:'radar-axis'}));
  }
  const results=chapters.map((chapter,i)=>chapter.answered?point(i,(chapter.answered-chapter.wrong)/chapter.answered):null);
  if(results.every(Boolean)){
    children.push(svg('polygon',{points:coordinates(results),class:'radar-area'}));
  }else{
    for(const [i,a] of results.entries()){
      const b=results[(i+1)%results.length];
      if(a&&b)children.push(svg('line',{x1:a[0],y1:a[1],x2:b[0],y2:b[1],class:'radar-line'}));
    }
  }
  for(const [i,chapter] of chapters.entries()){
    const group=svg('g',{class:'radar-chapter',role:'button',tabindex:0,
      'data-chapter':chapter.number,'aria-controls':'section-accuracy-panel',
      'aria-label':`第 ${chapter.number} 章 ${chapter.name}，查看小节正确率`,
      'aria-expanded':String(chapter.number===selected)});
    const [lx,ly]=point(i,1.30);
    const [x1,y1]=point(i,.23),[x2,y2]=point(i,1.15);
    group.append(svg('line',{x1,y1,x2,y2,class:'radar-hit-axis'}));
    group.append(svg('rect',{x:lx-26,y:ly-12,width:52,height:24,rx:4,class:'radar-hit-label'}));
    const label=svg('text',{x:lx,y:ly,'text-anchor':'middle','dominant-baseline':'middle',class:'radar-label'});
    label.textContent=`第 ${chapter.number} 章`;
    group.append(label);
    const marker=results[i];
    if(marker){
      group.append(svg('circle',{cx:marker[0],cy:marker[1],r:4,class:'radar-point','data-chapter':chapter.number}));
      if(chapter.answered>chapter.wrong)group.append(svg('circle',{cx:marker[0],cy:marker[1],r:10,class:'radar-hit-point'}));
    }
    children.push(group);
  }
  chart.replaceChildren(...children);
}

function renderAccuracyRows(list,entries,selected){
  list.replaceChildren(...entries.map(entry=>{
    const row=document.createElement('li');
    row.className='chapter-result';
    const name=document.createElement(entry.number?'button':'span');
    if(entry.number){
      name.type='button';name.className='accuracy-chapter-button';name.dataset.chapter=entry.number;
      name.setAttribute('aria-controls','section-accuracy-panel');
      name.setAttribute('aria-expanded',String(entry.number===selected));
    }
    name.textContent=entry.number?`${entry.number}. ${entry.name}`:`${entry.code} ${entry.name}`;
    const value=document.createElement('strong');
    value.textContent=entry.answered?`${Math.round((entry.answered-entry.wrong)/entry.answered*100)}%`:'未作答';
    value.classList.toggle('unattempted',!entry.answered);
    const count=document.createElement('small');
    count.textContent=entry.answered?`${entry.answered-entry.wrong} / ${entry.answered}`:'';
    row.append(name,value,count);
    if(Object.hasOwn(entry,'size')){
      const details=document.createElement('div');
      details.className='section-practice-detail';
      const accuracy=(correct,total)=>total?`${Math.round(correct/total*100)}%（${correct}/${total}）`:'—';
      const history=document.createElement('span');
      history.className='section-attempt-summary';
      history.textContent=`已练 ${entry.solved}/${entry.size} · 首答 ${accuracy(entry.firstCorrect,entry.firstAttempts)} · 复练 ${accuracy(entry.repeatCorrect,entry.repeats)}`;
      if(entry.unknownFirst){
        const old=document.createElement('small');
        old.textContent=`${entry.unknownFirst} 道旧题的首答顺序未知，仍计入总正确率。`;
        history.append(document.createElement('br'),old);
      }
      const practice=document.createElement('button');
      practice.type='button';practice.className='text-button section-practice-button';
      practice.dataset.section=entry.code;practice.disabled=!entry.size;
      practice.textContent=entry.size?`练本节 ${Math.min(10,entry.size)} 题 →`:'练本节';
      details.append(history,practice);
      row.append(details);
    }
    return row;
  }));
}

'use strict';

function buildPrintPaper(target,questions,minutes,answerKey){
  const element=(tag,contents,className)=>{
    const node=document.createElement(tag);
    if(contents!==undefined)node.textContent=contents;
    if(className)node.className=className;
    return node;
  };
  const header=element('header',undefined,'paper-heading');
  const questionCount=questions.length;
  const timing=`${minutes} minute${minutes===1?'':'s'}`;
  const code=questions[0].question_id.slice(0,4);
  const asPaper=code.startsWith('97');
  const subject=['0620','9701'].includes(code)?'Chemistry':'Physics';
  header.append(element('h1',`${asPaper?'AS':'IGCSE'} ${subject} ${code}`),
    element('p',`Paper ${asPaper?1:2} Practice · ${questionCount} question${questionCount===1?'':'s'} · ${timing}`),
    element('p','Name: ______________________________     Date: ______________','paper-name'));
  const paper=element('div',undefined,'paper-document');
  paper.append(header);
  for(const [index,question] of questions.entries()){
    const item=element('article',undefined,'printed-question electronic-question');
    if(question.electronic_content.body.blocks.some(block=>block.type==='figure'&&block.source_layout)){
      item.classList.add('printed-source-layout');
    }
    item.append(element('h2',`Question ${index+1}`));
    renderQuestionContent(item,question.electronic_content.body,question.question_id);
    item.append(element('p',examSource(question),'paper-source'));
    paper.append(item);
  }
  if(answerKey){
    const answers=element('section',undefined,'paper-key');
    answers.append(element('h2','Answer Key'));
    const table=element('table');
    const columns=element('thead');
    const heading=element('tr');
    for(const label of ['No.','Answer','Syllabus','Source']){
      const cell=element('th',label);
      cell.scope='col';
      heading.append(cell);
    }
    columns.append(heading);
    const rows=element('tbody');
    for(const [index,question] of questions.entries()){
      const row=element('tr');
      for(const value of [index+1,question.correct_option,question.primary_objective,
        examSource(question)]){
        row.append(element('td',value??''));
      }
      rows.append(row);
    }
    table.append(columns,rows);
    answers.append(table);paper.append(answers);
  }
  target.replaceChildren(paper);
}

'use strict';

function shuffled(items){
  const ordered=[...items];
  for(let i=ordered.length-1;i>0;i--){
    const j=Math.floor(Math.random()*(i+1));
    [ordered[i],ordered[j]]=[ordered[j],ordered[i]];
  }
  return ordered;
}

function downloadStudyFile(blob,name){
  const url=URL.createObjectURL(blob);
  const link=document.createElement('a');
  link.href=url;link.download=name;
  document.body.append(link);link.click();link.remove();
  setTimeout(()=>URL.revokeObjectURL(url),1000);
}

function studySource(question){
  return {questionId:question.question_id,sourceFile:question.qp_filename,
    page:question.source_page,questionNumber:question.original_question_number,
    syllabus:question.primary_objective,contentVersion:question.electronic_content?.version,
    markScheme:question.ms_filename,markSchemePage:question.ms_pdf_page};
}

function createStudyController(){
  const cache=new Map();
  let activeLoad,shown=false,index=0,wrongOnly=false,changing=false,submitting=false,exporting=false,exportTimer;
  let reportQuestion=null,reportId=null;

  async function loadQuestions(ids){
    if(ids.some(id=>!cache.has(id))){
      const key=ids.join(',');
      if(activeLoad?.key!==key){
        const params=new URLSearchParams({ids:key});
        const promise=api('/api/study?'+params).then(({questions})=>{
          for(const question of questions)cache.set(question.question_id,question);
        });
        activeLoad={key,promise};
      }
      const pending=activeLoad;
      try{await pending.promise;}
      finally{if(activeLoad===pending)activeLoad=null;}
    }
    return ids.map(id=>cache.get(id));
  }

  function scopedQuestions(){
    const range=new Set([...$('paper-scope').querySelectorAll('input:checked')].map(input=>input.value));
    return allQuestions.filter(item=>!range.size||range.has(sectionsById.get(item.question_id)));
  }

  for(const [chapter,name] of chapterNames.entries()){
    const sections=[...syllabusSections].filter(([code])=>code.startsWith(chapter+1+'.'));
    if(!sections.length)continue;
    const group=document.createElement('fieldset');
    const title=document.createElement('legend');
    title.textContent=`第 ${chapter+1} 章 · ${name}`;
    group.append(title);
    for(const [code,title] of sections){
      const label=document.createElement('label');
      const input=document.createElement('input');
      input.type='checkbox';input.value=code;
      label.append(input,`${code} ${title}`);
      group.append(label);
    }
    $('paper-scope').append(group);
  }
  function showPool(){
    $('paper-available').textContent=`可抽 ${scopedQuestions().length} 题`;
    $('paper-setup-error').hidden=true;
  }
  $('paper-scope').addEventListener('change',showPool);
  $('paper-count').addEventListener('input',()=>{
    const count=$('paper-count').valueAsNumber;
    if(count>=1&&count<=40)$('paper-minutes').value=Math.ceil(count*(asPaper?75:45)/40);
    $('paper-setup-error').hidden=true;
  });

  async function createSession(items,{mode,minutes=0,section=null}){
    if(progress.study?.stage==='active'){
      await enterStudy();
      toast('已有一套练习正在进行，交卷后可开始新的一套。');
      return;
    }
    const generation=progress.generation;
    const ids=items.map(item=>item.question_id);
    await loadQuestions(ids);
    if(generation!==progress.generation)return;
    const session={id:crypto.randomUUID(),mode,minutes,section,ids,
      stage:mode==='timed'?'ready':'active',answers:{},deadline:null};
    const stored=await progress.changeStudy(current=>current?.stage==='active'?null:{study:session});
    if(stored)await enterStudy();
  }

  function currentQuestion(){
    return cache.get(progress.study?.ids[index]);
  }

  async function enterStudy(){
    if(!progress.study)return;
    index=0;wrongOnly=false;shown=true;
    $('study-title').textContent='正在读取试卷…';
    $('study-meta').textContent='';$('study-score').hidden=true;
    $('study-active').hidden=true;$('study-ready').hidden=true;$('study-pdf-actions').hidden=true;
    $('study-view').hidden=false;$('workspace').hidden=true;$('learning-progress').hidden=true;
    await render();
    if(shown){
      $('study-title').focus({preventScroll:true});
      $('study-view').scrollIntoView({block:'start'});
    }
  }

  function leaveStudy(){
    shown=false;$('study-view').hidden=true;$('workspace').hidden=false;$('learning-progress').hidden=false;
    renderDirectory();paintNavigation();paintQuestionProgress();
    $('study-entry').scrollIntoView({block:'start'});
  }

  function sync(){
    const session=progress.study;
    $('resume-study').hidden=!session;
    if(session)$('resume-study').textContent=session.stage==='submitted'?'查看上次测验':session.stage==='ready'?'打开已组试卷':'继续练习';
    if(!session&&shown){
      if($('study-submit-dialog').open)$('study-submit-dialog').close();
      leaveStudy();
    }
    if(session&&shown)void render().catch(error=>toast(error.message));
  }

  function visibleIndices(session){
    return session.ids.map((_,i)=>i).filter(i=>!wrongOnly||session.answers[session.ids[i]]!==cache.get(session.ids[i]).correct_option);
  }

  async function render(){
    const session=progress.study;
    if(!shown||!session)return;
    await loadQuestions(session.ids);
    if(!shown||progress.study?.id!==session.id||progress.study.revision!==session.revision)return;
    const {mode,stage,section,ids,answers}=session;
    const review=stage==='submitted';
    const ready=stage==='ready';
    const answered=Object.keys(answers).length;
    const timed=mode==='timed';
    $('study-title').textContent=timed?'Paper 2 限时测验':`${section} ${syllabusSections.get(section)}专项练习`;
    $('study-meta').textContent=`${ids.length} 题 · ${timed?`${session.minutes} 分钟`:'即时反馈'}`;
    $('study-ready').hidden=!ready;$('study-active').hidden=ready;
    $('study-pdf-actions').hidden=!timed||(!ready&&!review);
    $('study-score').hidden=!review;
    if(review){
      const correct=ids.filter(id=>answers[id]===cache.get(id).correct_option).length;
      $('study-score').textContent=`得分 ${correct} / ${ids.length} · 错 ${answered-correct} 题 · 未答 ${ids.length-answered} 题`;
    }
    if(ready)return;
    const positions=visibleIndices(session);
    if(!positions.includes(index))index=positions[0]??0;
    const question=currentQuestion();
    const option=answers[question.question_id];
    const reveal=review||(!timed&&Boolean(option));
    $('study-position').textContent=`第 ${index+1} / ${ids.length} 题 · 已答 ${answered} 题`;
    $('study-clock').hidden=!timed||review;
    $('study-mistakes').hidden=!review||ids.every(id=>answers[id]===cache.get(id).correct_option);
    $('study-mistakes').textContent=wrongOnly?'查看全部题':'只看错题与未答';
    $('study-mistakes').setAttribute('aria-pressed',String(wrongOnly));
    $('study-prev').disabled=positions.indexOf(index)<=0;
    $('study-next').disabled=positions.indexOf(index)>=positions.length-1;
    $('study-submit').hidden=review;
    $('study-submit').textContent=timed?'交卷':'结束练习';

    $('study-question-grid').replaceChildren(...positions.map(i=>{
      const button=document.createElement('button');
      const id=ids[i];
      button.type='button';button.className='study-number';button.textContent=i+1;
      button.setAttribute('aria-current',String(index===i));
      button.setAttribute('aria-label',`第 ${i+1} 题${answers[id]?'，已答':''}`);
      button.classList.toggle('answered',Boolean(answers[id]));
      if(review&&answers[id]!==cache.get(id).correct_option)button.classList.add('missed');
      button.addEventListener('click',()=>goTo(i));
      return button;
    }));
    const article=$('study-question');
    article.replaceChildren();
    renderQuestionContent(article,question.electronic_content.body,question.question_id,
      label=>void choose(question,label));
    for(const button of article.querySelectorAll('.choice-button')){
      const selected=button.dataset.choice===option;
      button.setAttribute('aria-pressed',String(selected));
      button.disabled=reveal;
      const surface=button.closest('.choice-row')||button;
      surface.classList.toggle('is-selected',selected);
      surface.classList.toggle('is-correct',reveal&&button.dataset.choice===question.correct_option);
      surface.classList.toggle('is-incorrect',reveal&&selected&&option!==question.correct_option);
    }
    const result=$('study-feedback');
    result.hidden=!reveal&&!(timed&&option);
    result.textContent=reveal
      ? `${option?option===question.correct_option?'回答正确':'回答错误':'未作答'} · 标准答案 ${question.correct_option} · 考纲 ${question.primary_objective}`
      : option?`已选择 ${option}`:'';
    tick();
  }

  function goTo(position){
    if(position===undefined)return;
    index=position;
    void render().then(()=>{
      $('study-status')?.scrollIntoView({block:'start'});
    }).catch(error=>toast(error.message));
  }

  async function choose(question,option){
    if(changing)return;
    const session=progress.study;
    if(!session||session.stage!=='active'||!session.ids.includes(question.question_id))return;
    changing=true;
    try{
      await progress.changeStudy(current=>{
        if(current?.id!==session.id||current.stage!=='active'||(current.deadline&&Date.now()>=current.deadline))return null;
        const id=question.question_id;
        if(current.answers[id]===option||(current.mode==='practice'&&current.answers[id]))return null;
        const study={...current,answers:{...current.answers,[id]:option}};
        return {study,attempts:current.mode==='practice'?[{id,option,isCorrect:option===question.correct_option}]:[]};
      });
    }catch(error){toast(error.message||'作答未保存，请重试。');}
    finally{changing=false;tick();}
  }

  async function finish(){
    const session=progress.study;
    if(submitting||session?.stage!=='active')return;
    submitting=true;
    try{
      await loadQuestions(session.ids);
      const stored=await progress.changeStudy(current=>{
        if(current?.id!==session.id||current.stage!=='active')return null;
        const attempts=current.mode==='timed'?Object.entries(current.answers).map(([id,option])=>({
          id,option,isCorrect:option===cache.get(id).correct_option,
        })):[];
        return {study:{...current,stage:'submitted'},attempts};
      });
      if($('study-submit-dialog').open)$('study-submit-dialog').close();
      if(shown&&stored?.stage==='submitted')$('study-title').scrollIntoView({block:'start'});
    }catch(error){toast(error.message||'交卷失败，请重试。');}
    finally{submitting=false;}
  }

  function tick(){
    const session=progress.study;
    if(session?.stage!=='active'||!session.deadline)return;
    const seconds=Math.max(0,Math.ceil((session.deadline-Date.now())/1000));
    if(shown)$('study-clock').textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;
    if(!seconds)void finish();
  }

  async function exportPaper(){
    const session=progress.study;
    if(exporting||!session||session.mode!=='timed'||session.stage==='active')return;
    exporting=true;
    const button=$('download-study-pdf');
    const answerKey=$('include-answer-key').checked;
    button.disabled=true;button.textContent='正在排版…';
    try{
      if(true){
        const questions=await loadQuestions(session.ids);
        const target=$('printed-paper');
        buildPrintPaper(target,questions,session.minutes,answerKey);
        await Promise.all([...target.querySelectorAll('img')].map(async image=>{await image.offlineReady;await image.decode();}));
        document.body.classList.add('printing-paper');
        window.print();
        document.body.classList.remove('printing-paper');
        target.replaceChildren();
      }else{
        const response=await postAction('/api/paper', {ids:session.ids,minutes:session.minutes,answerKey});
        const name=asPage?'9702-AS-Paper1':'0625-Paper2';
        downloadStudyFile(await response.blob(),name+(answerKey?'-with-answer-key.pdf':'.pdf'));
      }
    }catch(error){
      toast(error.message||'PDF 生成失败，请重试。');
    }finally{
      exporting=false;button.disabled=false;
      button.textContent=true?'打印 / 另存 PDF':'导出 PDF';
    }
  }

  function openReport(question){
    if(!question?.electronic_content)return;
    reportQuestion=question;reportId=crypto.randomUUID();
    $('report-form').reset();$('report-submit').disabled=false;$('report-message').textContent='';
    $('report-source').textContent=examSource(question);
    $('report-dialog').showModal();
  }
  $('report-form').addEventListener('submit',async event=>{
    event.preventDefault();
    const note=$('report-note').value.trim();
    if(!note){$('report-message').textContent='请填写具体问题。';return;}
    const source=studySource(reportQuestion);
    const request={reportId,questionId:source.questionId,contentVersion:source.contentVersion,
      category:$('report-category').value,note};
    $('report-submit').disabled=true;
    try{
      if(true){
        const file={...request,source,reportedAt:new Date().toISOString()};
        downloadStudyFile(new Blob([JSON.stringify(file,null,2)+'\n'],{type:'application/json'}),`${source.questionId.slice(0,4)}-report-${reportId}.json`);
        if(reportId===request.reportId)$('report-message').textContent='报错单已生成。请将该文件交给教师。';
      }else{
        await postAction('/api/report',request);
        if(reportId===request.reportId)$('report-message').textContent='报错已保存到本机题库的报错记录。';
      }
    }catch(error){
      if(reportId!==request.reportId)return;
      $('report-message').textContent=error.message||'保存失败，请重试。';
      $('report-submit').disabled=false;
    }
  });

  $('open-paper-setup').disabled=false;
  $('open-paper-setup').addEventListener('click',()=>{showPool();$('paper-setup').showModal();});
  $('paper-setup-form').addEventListener('submit',async event=>{
    event.preventDefault();
    const help=$('paper-setup-error');
    const action=event.submitter;
    const pool=scopedQuestions();
    const count=$('paper-count').valueAsNumber;
    const minutes=$('paper-minutes').valueAsNumber;
    if(!Number.isInteger(count)||count<1||count>40||!Number.isInteger(minutes)||minutes<1||minutes>180){
      help.textContent='请输入 1–40 道题及 1–180 分钟。';help.hidden=false;
      return;
    }
    if(count>pool.length){
      help.textContent=`范围内只有 ${pool.length} 题。请选择更少题数或扩大范围。`;help.hidden=false;
      return;
    }
    action.disabled=true;
    try{
      await createSession(shuffled(pool).slice(0,count),{mode:'timed',minutes});
      if($('paper-setup').open)$('paper-setup').close();
      if(shown)$('study-title').focus({preventScroll:true});
    }catch(error){help.textContent=error.message;help.hidden=false;}
    finally{action.disabled=false;}
  });
  $('section-accuracy').addEventListener('click',event=>{
    const section=event.target.closest('.section-practice-button')?.dataset.section;
    if(!section||changing)return;
    const pool=allQuestions.filter(item=>sectionsById.get(item.question_id)===section);
    const preferWrong=$('section-priority').value==='wrong';
    const unseen=item=>!progress.records.has(item.question_id);
    const priority=item=>preferWrong?(isWrong(item.question_id)?0:unseen(item)?1:2):(unseen(item)?0:1);
    const chosen=shuffled(pool).sort((a,b)=>priority(a)-priority(b)).slice(0,10);
    changing=true;
    void createSession(chosen,{mode:'practice',section}).catch(error=>toast(error.message))
      .finally(()=>changing=false);
  });
  $('start-timed-study').addEventListener('click',async()=>{
    const id=progress.study?.id;
    try{
      await progress.changeStudy(current=>current?.id===id&&current.stage==='ready'
        ?{study:{...current,stage:'active',deadline:Date.now()+current.minutes*60000}}:null);
    }catch(error){toast(error.message);}
  });
  $('resume-study').addEventListener('click',()=>void enterStudy().catch(error=>toast(error.message)));
  $('leave-study').addEventListener('click',leaveStudy);
  for(const [id,direction] of [['study-prev',-1],['study-next',1]])$(id).addEventListener('click',()=>{
    const positions=visibleIndices(progress.study);
    goTo(positions[positions.indexOf(index)+direction]);
  });
  $('study-mistakes').addEventListener('click',()=>{wrongOnly=!wrongOnly;void render().catch(error=>toast(error.message));});
  $('study-submit').addEventListener('click',()=>{
    const {ids,answers}=progress.study;
    $('study-submit-summary').textContent=`已答 ${Object.keys(answers).length} / ${ids.length} 题。`;
    $('study-submit-dialog').showModal();
  });
  $('study-submit-form').addEventListener('submit',event=>{event.preventDefault();void finish();});
  for(const button of document.querySelectorAll('[data-close]'))button.addEventListener('click',()=>$(button.dataset.close).close());
  $('report-question').addEventListener('click',()=>openReport(state.detail));
  $('study-report').addEventListener('click',()=>openReport(currentQuestion()));
  $('download-study-pdf').addEventListener('click',()=>void exportPaper());
  if(true){
    $('report-submit').textContent='下载报错单';
    $('download-study-pdf').textContent='打印 / 另存 PDF';
  }
  setInterval(tick,1000);
  document.addEventListener('visibilitychange',tick);
  sync();
  return {sync};
}

