const topicSummary = text => String(text ?? '').replace(/[（(]\s*(?:Core|Supplement)(?:\s*[/与、]\s*(?:Core|Supplement))*\s*[)）]/gi,'').replace(/\b(?:Core|Supplement)\b/g,'').trim();
const progress = new PracticeProgress(progressChanged,pageBank);
