function buildRandomRanges(chapters,titles){
  const panel=$('random-chapters');
  for(const [offset,name] of chapterNames.entries()){
    const number=offset+1;
    const sections=Object.entries(chapters).filter(([code])=>code.startsWith(number+'.'));
    if(!sections.length)continue;
    const group=document.createElement('fieldset');group.className='range-group';
    const legend=document.createElement('legend');
    const parentLabel=document.createElement('label');const parent=document.createElement('input');parent.type='checkbox';
    parentLabel.append(parent,`第 ${number} 章 · ${name}`);legend.append(parentLabel);group.append(legend);
    const children=sections.map(([code,count])=>{
      const label=document.createElement('label');const input=document.createElement('input');input.type='checkbox';input.value=code;input.dataset.count=count;
      label.append(input,`${code} ${topicSummary(titles[code])}（${count}）`);group.append(label);
      return input;
    });
    const updateParent=()=>{
      parent.checked=children.every(input=>input.checked);
      parent.indeterminate=!parent.checked&&children.some(input=>input.checked);
    };
    parent.addEventListener('change',()=>{for(const input of children)input.checked=parent.checked;});
    group.addEventListener('change',()=>{updateParent();updateRandomCount();});
    panel.append(group);
  }
}
function selectedRanges(){return [...$('random-chapters').querySelectorAll('input[data-count]:checked')];}
function updateRandomCount(){
  const ranges=selectedRanges();
  const collection=collectionLabels[state.view];
  $('random-summary').textContent=ranges.length
    ? `随机范围 · ${ranges.length} 小节${collection?'':` / ${ranges.reduce((total,input)=>total+Number(input.dataset.count),0)} 题`}`
    : `随机范围 · ${collection||'全部章节'}`;
  $('random-help').textContent=collection?`在「${collection}」内按所选分册抽题。`:'按题目分册抽取，未勾选时从全库抽题。';
}
async function chooseRandom(){
  if(randomRequest||!allQuestions)return;
  const ranges=new Set(selectedRanges().map(input=>input.value));
  randomRequest=true;paintNavigation();
  try{
    const candidates=allQuestions.filter(item=>visibleInDirectory(item)&&item.question_id!==state.selected
      &&(!ranges.size||ranges.has(item.chapter_code)));
    if(!candidates.length){toast('所选范围内没有其他题目，请扩大随机范围。');return;}
    const {question_id:id}=candidates[Math.floor(Math.random()*candidates.length)];
    $('random-ranges').open=false;
    if(state.view!=='skipped'&&state.items.some(item=>item.question_id===id)){
      await selectQuestion(id,{scroll:true});
    }else{
      clearFilters();
      if(state.view==='skipped')state.view='included';
      updateViewButtons();state.selected=id;await loadList({scroll:true});
    }
  }catch(error){toast(error.message);}
  finally{randomRequest=false;paintNavigation();}
}

function wrongCount(){
  let count=0;
  for(const [id,record] of progress.records){
    if(sectionsById.has(id)&&isInWrongBook(record))count++;
  }
  return count;
}
function paintProgress(){
  const byAttempts=!practiceTools.testMode();
  const chapters=chapterNames.map((name,index)=>({name,number:index+1,answered:0,wrong:0}));
  const sections=new Map([...syllabusSections].map(([code,name])=>[code,{code,name,answered:0,wrong:0,
    size:sectionSizes.get(code)||0,solved:0,firstAttempts:0,firstCorrect:0,repeats:0,repeatCorrect:0,unknownFirst:0}]));
  const appendix={answered:0,wrong:0};
  let solved=0;
  for(const [id,record] of progress.records){
    if(!sectionsById.has(id))continue;
    solved++;
    const bucket=sections.get(sectionsById.get(id))||appendix;
    bucket.answered+=byAttempts?record.attempts:1;
    bucket.wrong+=byAttempts?record.attempts-record.correct:Number(isInWrongBook(record));
    if(bucket!==appendix){
      bucket.solved++;
      const split=attemptBreakdown(record);
      if(split.firstCorrect===null)bucket.unknownFirst++;
      else{
        bucket.firstAttempts++;bucket.firstCorrect+=Number(split.firstCorrect);
      }
      bucket.repeats+=split.repeats;bucket.repeatCorrect+=split.repeatCorrect;
    }
  }
  for(const section of sections.values()){
    const chapter=chapters[Number(section.code.split('.')[0])-1];
    chapter.answered+=section.answered;
    chapter.wrong+=section.wrong;
  }
  $('progress-method').textContent=byAttempts
    ? '正确率 = 答对次数 ÷ 作答次数，含复练。点选章节可查看小节。'
    : '已答题数按题去重。正确率 =（已答题数 − 错题本题数）÷ 已答题数。点选章节可查看小节。';
  const storageNote=progress.persistent?'进度保存在当前浏览器。':'此浏览器暂时无法保存进度，记录仅保留在本次页面。';
  $('progress-storage').textContent=storageNote;
  $('storage-status').hidden=progress.persistent;
  $('wrong-count').textContent=wrongCount();
  $('progress-summary').textContent=`已做 ${solved} 题`;
  $('appendix-progress').hidden=!appendix.answered;
  $('appendix-progress').textContent=`附录等独立考点 · ${byAttempts?'答对 / 作答':'已答且不在错题本 / 已答'} ${appendix.answered-appendix.wrong} / ${appendix.answered}`;
  $('reset-progress').disabled=!allQuestions;
  const activeChapters=(asPage||chemistryPage)?chapters.filter(chapter=>
    [...sections.keys()].some(code=>code.startsWith(chapter.number+'.'))):chapters;
  $('accuracy-chart').toggleAttribute('hidden',activeChapters.length<3);
  if(activeChapters.length>=3)renderAccuracyRadar($('accuracy-chart'),activeChapters,expandedChapter);
  renderAccuracyRows($('chapter-accuracy'),activeChapters,expandedChapter);
  $('section-accuracy-panel').hidden=expandedChapter===null;
  if(expandedChapter!==null){
    $('section-accuracy-title').textContent=`第 ${expandedChapter} 章 · ${chapters[expandedChapter-1].name}小节正确率`;
    renderAccuracyRows($('section-accuracy'),[...sections.values()]
      .filter(section=>section.code.startsWith(expandedChapter+'.')));
  }
}
