const mathTags=new Set(['mi','mn','mo','mtext','mrow','mfrac','msup','msub','msubsup','msqrt','mmultiscripts','mprescripts','none']);
function mathNode(tree){
  if(!mathTags.has(tree.tag))throw new Error('无法显示公式');
  const element=document.createElementNS('http://www.w3.org/1998/Math/MathML',tree.tag);
  for(const child of tree.children)element.append(typeof child==='string'?document.createTextNode(child):mathNode(child));
  return element;
}
function appendRuns(target,runs){
  for(const run of runs){
    if(Object.hasOwn(run,'text'))target.append(document.createTextNode(run.text));
    else if(run.math){const math=document.createElementNS('http://www.w3.org/1998/Math/MathML','math');math.append(mathNode(run.math));target.append(math);}
  }
}
function contentTable(headers,rows,choices=false,groups=[],interactive=false,onChoose=null){
  const wrap=document.createElement('div');wrap.className='table-scroll';wrap.tabIndex=0;
  const table=document.createElement('table');table.className='question-table';
    const head=document.createElement('thead');const tr=document.createElement('tr');
    if(groups.length){const grouped=document.createElement('tr');
      if(choices){const blank=document.createElement('th');blank.textContent='';grouped.append(blank);}
      for(const group of groups){const th=document.createElement('th');th.scope='colgroup';th.colSpan=group.span;appendRuns(th,group.runs);grouped.append(th);}
      head.append(grouped);
    }
  if(choices){const th=document.createElement('th');th.scope='col';th.textContent='';tr.append(th);}
  for(const header of headers){const th=document.createElement('th');th.scope='col';appendRuns(th,header);tr.append(th);}
  if(headers.length||choices){head.append(tr);table.append(head);}
  const body=document.createElement('tbody');
  for(const row of rows){const rr=document.createElement('tr');
    if(choices){
      const th=document.createElement('th');th.scope='row';
      if(interactive){
        const option=choiceButton(row.label,onChoose);
        option.textContent=row.label;th.append(option);
        rr.className='choice-row';
        rr.addEventListener('click',event=>{
          if(event.target!==option&&!option.disabled&&!window.getSelection()?.toString())option.click();
        });
      }else th.textContent=row.label;
      rr.append(th);
    }
    for(const cell of (choices?row.cells:row)){const td=document.createElement('td');appendRuns(td,cell);rr.append(td);}
    body.append(rr);
  }
  table.append(body);wrap.append(table);return wrap;
}
function choiceButton(label,onChoose){
  const button=document.createElement('button');button.type='button';button.className='choice-button';
  button.dataset.choice=label;button.setAttribute('aria-pressed','false');
  button.addEventListener('click',()=>onChoose(label));return button;
}
function appendBlocks(target,blocks,figureOptions,onChoose){
  for(const block of blocks){
    if(block.type==='paragraph'){const p=document.createElement('p');appendRuns(p,block.runs);target.append(p);}
    else if(block.type==='list'){const ul=document.createElement(block.ordered?'ol':'ul');for(const item of block.items){const li=document.createElement('li');appendRuns(li,item);ul.append(li);}target.append(ul);}
    else if(block.type==='table')target.append(contentTable(block.headers,block.rows));
    else if(block.type==='figure'){
      const figure=document.createElement('figure');const img=document.createElement('img');loadOfflineFigure(img,block.figure_id);img.alt=block.alt;
      img.addEventListener('error',()=>{const note=document.createElement('p');note.textContent='图形暂时无法显示，请刷新页面重试。';figure.replaceChildren(note);});
      const caption=document.createElement('figcaption');caption.textContent=block.source_layout?'原卷矢量排版':'矢量重绘 · 可与原卷对照';
      const canvas=document.createElement('div');canvas.className='figure-canvas';canvas.append(img);
      const options=figureOptions?.[block.figure_id];
      if(options){
        canvas.style.setProperty('--figure-min-width',options.minWidth+'px');
        for(const [label,x,y] of options.points){
          const button=choiceButton(label,onChoose);
          button.classList.add('figure-choice');button.textContent=label;
          button.style.left=x+'%';button.style.top=y+'%';canvas.append(button);
        }
        const viewport=document.createElement('div');viewport.className='figure-viewport';viewport.append(canvas);
        if(options.minWidth>230){
          viewport.tabIndex=0;viewport.setAttribute('aria-label','图形选项区域');
          const hint=document.createElement('span');
          hint.className=options.minWidth>560?'figure-swipe always':'figure-swipe';
          hint.textContent=' · 图形较宽时可左右滑动查看选项';caption.append(hint);
        }
        figure.append(viewport);
      }else{
        figure.append(canvas);
      }
      figure.append(caption);target.append(figure);
    }
  }
}
function renderQuestionContent(article,body,questionId,onChoose=null){
  const figureOptions=onChoose&&body.choices_in_figure?(body.figure_choice_layout||figureChoiceAnchors[questionId]):null;
  appendBlocks(article,body.blocks,figureOptions,onChoose);
  if(!body.choices_in_figure&&body.choice_headers.length)article.append(contentTable(body.choice_headers,body.choices,true,body.choice_header_groups||[],Boolean(onChoose),onChoose));
  else if(!body.choices_in_figure){
    const list=document.createElement('ul');list.className='electronic-choices';
    for(const choice of body.choices){
      const li=document.createElement('li');
      const option=onChoose?choiceButton(choice.label,onChoose):document.createElement('div');
      if(!onChoose)option.className='printed-choice';
      const letter=document.createElement('strong');letter.className='choice-label';letter.textContent=choice.label;
      const wording=document.createElement('span');appendRuns(wording,choice.cells[0]);
      option.append(letter,wording);li.append(option);list.append(li);
    }
    article.append(list);
  }
  appendBlocks(article,body.after_choices||[],figureOptions,onChoose);
}
function renderElectronic(body){
  const article=$('electronic-question');article.replaceChildren();
  const kicker=document.createElement('div');kicker.className='electronic-kicker';kicker.textContent=`QUESTION ${state.detail.original_question_number} · 1 MARK`;article.append(kicker);
  renderQuestionContent(article,body,state.detail.question_id,chooseAnswer);
  paintChoices();
}
function canPractice(){
  const d=state.detail;
  return Boolean(d?.status==='included'&&d.question_id===state.selected&&/^[ABCD]$/.test(d.correct_option));
}
function resetPractice(){
  state.answer=false;state.choice=null;
  $('answer-result').hidden=true;
  $('answer-letter').textContent='';$('answer-syllabus').textContent='';$('answer-source').textContent='';
  $('practice-feedback').textContent='';$('practice-feedback').hidden=true;
  const ready=canPractice();
  $('reveal-answer').disabled=!ready;$('reveal-answer').hidden=!ready;$('answer-panel').hidden=!ready;
  $('retry-question').hidden=true;
  paintChoices();
  practiceTools.paint();
}
function paintChoices(){
  const ready=canPractice();
  for(const button of $('electronic-question').querySelectorAll('.choice-button')){
    const selected=button.dataset.choice===state.choice;
    const correct=state.choice!==null&&button.dataset.choice===state.detail.correct_option;
    button.disabled=!ready||state.choice!==null;button.setAttribute('aria-pressed',String(selected));
    const surface=button.closest('.choice-row')||button;
    surface.classList.toggle('is-selected',selected);
    surface.classList.toggle('is-correct',correct);
    surface.classList.toggle('is-incorrect',selected&&!correct);
  }
}
function chooseAnswer(label){
  const d=state.detail;
  if(!canPractice()||state.choice!==null||!/^[ABCD]$/.test(label))return;
  state.choice=label;const correct=label===d.correct_option;
  paintChoices();
  const feedback=$('practice-feedback');feedback.hidden=false;feedback.className='practice-feedback '+(correct?'correct':'incorrect');
  feedback.textContent=correct?`回答正确！你选择了 ${label}。`:`回答错误。你选择了 ${label}，正确答案是 ${d.correct_option}。`;
  showAnswer();
  paintQuestionProgress();
  void progress.record(d.question_id,label,correct);
}
function showAnswer(){
  const d=state.detail;if(!d||d.status==='skipped')return;
  state.answer=true;$('reveal-answer').hidden=true;$('answer-result').hidden=false;
  $('answer-letter').textContent=`标准答案：${d.correct_option}`;
  const primary=d.topics.find(topic=>topic.topic_role==='PRIMARY');
  $('answer-syllabus').textContent=primary?`（考纲对应：${primary.reference_code}）`:'（考纲对应：待复核）';
  $('answer-source').textContent=examSource(d);
}

